def subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def has_tag(value,name):
    for item in subterms(value):
        if item[0]==name:
            return True
    return False

def owner_ok(value):
    return isinstance(value,list) and bool(value) and value[0] in ('receiving_party','party','named_recipient')

def class_tags(x,definitions):
    tags=set()
    todo=[x]
    seen=set()
    while todo:
        value=todo.pop()
        if not isinstance(value,list) or not value:
            continue
        name=value[0]
        if name=='representatives_of':
            key=str(value[1]) if len(value)>1 else ''
            if key not in seen:
                seen.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name=='internal_personnel_of' and len(value)>1 and owner_ok(value[1]):
            tags.add('employees_of')
        if name in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of'):
            if len(value)>1 and owner_ok(value[1]):
                tags.add(name)
            continue
        if name=='third_parties':
            tags.add(name)
            continue
        i=1
        while i<len(value):
            if isinstance(value[i],list):
                todo.append(value[i])
            i+=1
    return tags

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=collect_entries(premises)
    if task in ('nda-5','nda-7'):
        return disclosure_answer(task,entries)
    disposal=[]
    retention_permissions=[]
    retention_prohibitions=[]
    no_disposal=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0] in ('retention_prohibition','absolute_retention_prohibition'):
            retention_prohibitions.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            no_disposal.append(root)
    if task=='nda-16':
        endpoints=[]
        relevant=[]
        for term,root in disposal:
            if not (has_tag(term[2],'return_to') or has_tag(term[2],'destroy')):
                continue
            relevant.append(root)
            trigger=term[3]
            if has_tag(trigger,'agreement_termination') or has_tag(trigger,'service_termination') or has_tag(trigger,'relationship_termination') or has_tag(trigger,'relationship_nonformation_deadline') or has_tag(trigger,'purpose_completion'):
                endpoints.append(root)
        if endpoints:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(endpoints)}
        if relevant or no_disposal:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+no_disposal)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(retention_prohibitions)}
    full=[]
    relevant=[]
    for term,root in disposal:
        if has_tag(term[2],'return_to') or has_tag(term[2],'destroy'):
            relevant.append(root)
            if pb_all_material_disposal(term[2]):
                full.append(root)
    if full:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(full)}
    if relevant or no_disposal:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+no_disposal)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def disclosure_decision(task,entries):
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='complete_source_no_disclosure_permission':
            absence.append(root)
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose':
            continue
        if not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(root)
        tags=class_tags(action[2],definitions)
        if term[0]=='permission':
            permissions.append((root,tags,action[2]))
        else:
            prohibitions.append((root,tags,action[2]))
    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','independent_contractors_of'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[root]
            if has_tag(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    for root,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def collect_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for node in nodes:
        byid[node.get('id')]=node
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in byid:
                continue
            seen.add(node_id)
            node=byid[node_id]
            for term in subterms(node.get('term')):
                entries.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return entries

def role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='representatives_of':
            key=str(item[1]) if len(item)>1 else ''
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name=='internal_personnel_of' and len(item)>1 and owner_ok(item[1]):
            tags.add('employees_of')
        if name in ('employees_of','directors_of','officers_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of','consultants_of','agents_of','independent_contractors_of','lenders_of','third_parties'):
            if name=='third_parties' or (len(item)>1 and owner_ok(item[1])):
                tags.add(name)
            continue
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def disclosure_answer(task,entries):
    definitions=[]
    definition_roots=[]
    permissions=[]
    prohibitions=[]
    relevant=[]
    absence=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
        if term[0] in ('complete_source_no_disclosure_permission','complete_source_rule_absence'):
            absence.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not has_tag(action[1],'confidential_information'):
            continue
        relevant.append(root)
        item=(root,role_tags(action[2],definitions),action[2])
        if term[0]=='permission':
            permissions.append(item)
        else:
            prohibitions.append(item)
    wanted={'employees_of'} if task=='nda-5' else {'third_parties','consultants_of','agents_of','independent_contractors_of','legal_advisors_of','financial_advisors_of','professional_advisors_of','accountants_of'}
    for root,tags,recipient in permissions:
        if tags.intersection(wanted):
            used=[root]
            if has_tag(recipient,'representatives_of'):
                used.extend(definition_roots)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
    for root,tags,recipient in prohibitions:
        if has_tag(recipient,'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def pb_all_material_disposal(term):
    if not isinstance(term,list) or not term:
        return False
    todo=[term]
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        if item[0]=='source_disposal_material' and len(item)>2:
            choice=str(item[1])
            text=str(item[2]).casefold()
            if choice in ('all_source_stated_materials','information_copies_and_derivatives') and ('all ' in text or 'any and all' in text):
                return True
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return False
